int main(int argc, char *argv[])
{
    return regtool_main(argc, argv, DUMMY_FPGA_BASE_ADDR, DUMMY_FPGA_BASE_SIZE,
                        registers, (int)(sizeof(registers) / sizeof(registers[0])));
}
